class IntervalSet:
    """A set of real numbers represented as half-open intervals [start, end)."""

    def __init__(self, intervals=None):
        self._intervals = []  # sorted list of [start, end] lists
        if intervals is not None:
            for start, end in intervals:
                self.add(start, end)

    def add(self, start, end):
        if start >= end:
            return
        new_start = start
        new_end = end
        result = []
        inserted = False
        for s, e in self._intervals:
            if e < new_start:
                # Current interval is entirely before new interval (no adjacency)
                result.append((s, e))
            elif s > new_end:
                # Current interval is entirely after new interval (no adjacency)
                if not inserted:
                    result.append((new_start, new_end))
                    inserted = True
                result.append((s, e))
            else:
                # Overlapping or adjacent: merge
                new_start = min(new_start, s)
                new_end = max(new_end, e)
        if not inserted:
            result.append((new_start, new_end))
        self._intervals = result

    def remove(self, start, end):
        if start >= end:
            return
        result = []
        for s, e in self._intervals:
            if e <= start or s >= end:
                # No overlap
                result.append((s, e))
            else:
                # There is overlap
                if s < start:
                    result.append((s, start))
                if e > end:
                    result.append((end, e))
        self._intervals = result

    def contains(self, x):
        for s, e in self._intervals:
            if s <= x < e:
                return True
        return False

    def __contains__(self, x):
        return self.contains(x)

    def measure(self):
        return sum(e - s for s, e in self._intervals)

    def overlaps(self, start, end):
        if start >= end:
            return False
        for s, e in self._intervals:
            if s < end and e > start:
                return True
        return False

    def intervals(self):
        return list(self._intervals)

    def __len__(self):
        return len(self._intervals)

    def __bool__(self):
        return len(self._intervals) > 0

    def __eq__(self, other):
        if isinstance(other, IntervalSet):
            return self._intervals == other._intervals
        return NotImplemented
